(function(global){'use strict';global.hydrateFeatherIcons=function(scope,options){if(!scope){scope=document}
options=options||{};if(!window.feather){console.warn('[Feather Icons] Library not loaded. Icons will not render.');return!1}
if(typeof feather.replace!=='function'){console.warn('[Feather Icons] feather.replace() is not available.');return!1}
try{var selector=scope===document||scope.nodeType===9?document:scope;var icons=selector.querySelectorAll('[data-feather]');var missingIcons=[];var replaced=0;icons.forEach(function(icon){var iconName=icon.getAttribute('data-feather');if(iconName&&!feather.icons[iconName]){missingIcons.push(iconName);icon.setAttribute('data-feather','alert-circle');replaced++}});if(missingIcons.length>0){console.warn('[Feather Icons] Missing icon definitions: '+missingIcons.join(', ')+' (replaced with fallback)')}
if(scope===document||scope.nodeType===9){feather.replace(options)}else{feather.replace({root:scope,...options})}
return!0}catch(error){console.error('[Feather Icons] Error during replace:',error);return!1}};global.isFeatherAvailable=function(){return!!(window.feather&&typeof feather.replace==='function')};if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){if(window.feather){hydrateFeatherIcons()}})}else{if(window.feather){hydrateFeatherIcons()}}})(window)